; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: test (Test harness (port I/O console)), starts in normal mode
; ============================================================

			org #4000

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 4: r = Loader.Load("DATA.BIN", VarPtr(b(0)), 300)
			dw p_loader_load_c, str0, vp_arr_b, lit_300
			dw kw_vtov, var_loader_load_load, var_r

			; main.bas 5: Print "len"; r; b(0); b(1); b(199)
			dw kw_printstrvar, str1
			dw kw_printint, var_r
			dw kw_lptrtov8, arr_b, tmp0
			dw kw_printint, tmp0
			dw kw_lptrtov8, arr_b+1, tmp0
			dw kw_printint, tmp0
			dw kw_lptrtov8, arr_b+199, tmp0
			dw kw_printint, tmp0
			dw kw_printnl

			; main.bas 6: r = Loader.Load("NOPE.BIN", VarPtr(b(0)), 300)
			dw p_loader_load_c, str2, vp_arr_b, lit_300
			dw kw_vtov, var_loader_load_load, var_r

			; main.bas 7: Print "none"; r
			dw kw_printstrvar, str3
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 8: r = Loader.Load("DATA.BIN", VarPtr(b(0)), 100)
			dw p_loader_load_c, str0, vp_arr_b, lit_100
			dw kw_vtov, var_loader_load_load, var_r

			; main.bas 9: Print "big"; r
			dw kw_printstrvar, str4
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 10: r = Loader.Load("", VarPtr(b(0)), 100)
			dw p_loader_load_c, str5, vp_arr_b, lit_100
			dw kw_vtov, var_loader_load_load, var_r

			; main.bas 11: Print "bad"; r
			dw kw_printstrvar, str6
			dw kw_printint, var_r
			dw kw_printnl

			; main.bas 12: r = Loader.Load("data.bin", VarPtr(b(0)), 300)
			dw p_loader_load_c, str7, vp_arr_b, lit_300
			dw kw_vtov, var_loader_load_load, var_r

			; main.bas 13: Print "low"; r; b(5)
			dw kw_printstrvar, str8
			dw kw_printint, var_r
			dw kw_lptrtov8, arr_b+5, tmp0
			dw kw_printint, tmp0
			dw kw_printnl
			dw kw_stop

; ============================================================
; function load (normal mode)
; ============================================================

p_loader_load:

			; Loader.cls 17: Load = NotSupported
			dw kw_ltov, -1, var_loader_load_load
			dw p_loader_load_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================


p_loader_load_c:		; call load (normal)
			pop hl			; name
			ld de, var_loader_load_name
			ld b, 40
p_loader_load_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_loader_load_si0_e
			inc hl
			inc de
			djnz p_loader_load_si0
			xor a
			ld (de), a
p_loader_load_si0_e:
			pop hl			; addr
			ld de, var_loader_load_addr		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; maxlen
			ldi
			ldi
			ld hl, 0
			ld (var_loader_load_load), hl
			ld (p_loader_load_rs), sp
			ld sp, p_loader_load
			jp ntc_xn
p_loader_load_r:		; end of load
			ld sp, (p_loader_load_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_r:			dw 0
var_loader_load_load:			dw 0
p_loader_load_rs:			dw 0
var_loader_load_addr:			dw 0, 0		; parameters, one block
var_loader_load_maxlen		equ var_loader_load_addr + 2
			db 40			; capacity
var_loader_load_name:			ds 41
tmp0:			dw 0

; numbers passed by address (read only)
vp_arr_b:			dw arr_b
lit_300:			dw 300
lit_100:			dw 100

; ============================================================
; Strings
; ============================================================

str0:			db "DATA.BIN", 0
str1:			db "len", 0
str2:			db "NOPE.BIN", 0
str3:			db "none", 0
str4:			db "big", 0
str5:			db 0
str6:			db "bad", 0
str7:			db "data.bin", 0
str8:			db "low", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
	IF NTC_INTS					; (;@ints 0: a platform that never lets interrupts in - the Next's dot commands)
			ei
			nop					; an interrupt can be taken here
			di
	ENDIF
			ld sp, (ntc_ip)
			ret

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_srows:		db 25			; rows
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line

;## ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_putc - A = character: out, move on, new line after the last column
ntc_plat_putc:
			out (#fe), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pc_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pc_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ntc_plat_newline - column 0, next row (the harness scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			out (#f9), a
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_exit ntc_plat_data
ntc_plat_exit:
			jp (ix)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use (the harness's stack, below it, comes off too). Called on the real
; stack (call / ret), only by the Memory class.
ntc_plat_memtop:
			ld hl, #C000
			ret


ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack the caller's"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_b		equ ntc_bss + 0		; 300 bytes
ntc_bss_size	equ 300
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
